const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < input.length && input[offset] <= 32) {
            offset++;
        }
        if (offset >= input.length) return null;
        let res = 0;
        while (offset < input.length && input[offset] > 32) {
            res = res * 10 + (input[offset] - 48);
            offset++;
        }
        return res;
    }

    const S = nextInt();
    if (S === null) return;
    const T = nextInt();

    // Use a flattened 2D array / typed array for the adjacency matrix.
    // S <= 1000, so a matrix of (S + 1) * (S + 1) is ~1MB.
    const stride = S + 1;
    const adj = new Uint8Array(stride * stride);

    for (let i = 0; i < T; i++) {
        const u = nextInt();
        const v = nextInt();
        adj[u * stride + v] = 1;
        adj[v * stride + u] = 1;
    }

    const P = nextInt();
    let validCount = 0;

    for (let i = 0; i < P; i++) {
        const N = nextInt();
        let possible = true;
        let prev = nextInt();

        for (let j = 1; j < N; j++) {
            const curr = nextInt();
            if (possible) {
                if (adj[prev * stride + curr] === 0) {
                    possible = false;
                }
            }
            prev = curr;
        }

        if (possible) {
            validCount++;
        }
    }

    console.log(validCount);
}

solve();
